import math
dist=0.0
phase=0
said=False
def control(o):
 global dist,phase,said
 h=o['hitch_deg']
 if phase==0:
  dist+=max(0,o['motion']['v_mps'])*o['dt']
  if dist<0.9:
   return (0,0.4,150)
  phase=1
 if phase==1:
  if abs(o['motion']['v_mps'])>0.03: return (35,0,150)
  phase=2
 eq=math.degrees(math.atan2(2.5*math.sin(math.radians(h)),3.6+1.3*math.cos(math.radians(h))))
 steer=max(-44,min(44,eq+2*(h-15)))
 if h<18 and not said:
  said=True; wake('Trailer straightening; inspect next bend')
 return (steer,-0.3,150)

