import math
def control(obs):
    cam=obs.get('views',{}).get('camera')
    h=obs['hitch_deg']
    desired=0.0
    if cam:
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b+h)
            s=-d*math.cos(a); y=d*math.sin(a)
            if s>0.3 and abs(y)>1.0:
                sides[0 if y>0 else 1].append((s,y))
        vals=[]
        for pts in sides:
            if len(pts)>=2:
                mx=sum(p[0] for p in pts)/len(pts); my=sum(p[1] for p in pts)/len(pts)
                den=sum((p[0]-mx)**2 for p in pts)
                slope=sum((p[0]-mx)*(p[1]-my) for p in pts)/max(den,0.1)
                vals.append(my+slope*(5.5-mx))
        if len(vals)==2:
            centre=sum(vals)/2
            desired=math.degrees(math.atan(20.4*centre/(5.5**2)))
            desired=max(-35,min(35,desired))
    steer=0.38*h+1.4*(h-desired)
    return (max(-42,min(42,steer)),-0.85,-41)

